using System;
using Microsoft.Extensions.DependencyInjection;

interface IClock
{
    DateTime Now { get; }
}

class SystemClock : IClock
{
    public DateTime Now => DateTime.UtcNow;
}

class OrderService
{
    private readonly IClock clock;

    public OrderService()
    {
        clock = new SystemClock(); // TODO: inject the clock
    }

    public DateTime CreatedAt => clock.Now;
}

class Program
{
    static void Main()
    {
        var services = new ServiceCollection();
        services.AddScoped<OrderService>();
        var provider = services.BuildServiceProvider();
        Console.WriteLine(provider.GetRequiredService<OrderService>().CreatedAt);
    }
}
